    protected function setUpTraits()
    {
        $connection = $this->app['db']->connection();

        if ($connection->getDriverName() !== 'sqlite') {
            $connection->getSchemaBuilder()->dropAllTables();
            RefreshDatabaseState::$migrated = false;
        }

